/* CHEM-MAP TUTOR AI V3.0 — offline rules engine, not generative AI; no backend. */
(()=>{'use strict';
const KEY='chemmap-v2';const LEGACY_KEY='chemmap-v1';const CAT=window.CHEM_MAP_CATALOG||{};const SOURCES=window.CHEM_MAP_SOURCES||[];const TYPES={mcq:'Trắc nghiệm nhiều lựa chọn',tf:'Đúng / Sai (4 ý)',short:'Trả lời ngắn',essay:'Tự luận'};const LEVELS={NB:'Nhận biết',TH:'Thông hiểu',VD:'Vận dụng tính toán',VDC:'Vận dụng cao'};
const storage={load(){try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}},save(v){try{localStorage.setItem(KEY,JSON.stringify(v))}catch{alert('Không thể lưu dữ liệu vào trình duyệt. Vui lòng kiểm tra dung lượng lưu trữ.')}}};
let store=storage.load();if(!store||!Array.isArray(store.bank)||!Array.isArray(store.attempts)){
let old=null;try{old=JSON.parse(localStorage.getItem(LEGACY_KEY))}catch{}
const mine=Array.isArray(old?.bank)?old.bank.filter(q=>String(q.id).startsWith('USER-')):[];
const seen=new Set(window.CHEM_MAP_SEED.map(q=>q.id));
store={bank:[...structuredClone(window.CHEM_MAP_SEED),...mine.filter(q=>!seen.has(q.id)).map(q=>({...q,status:'draft'}))],attempts:Array.isArray(old?.attempts)?old.attempts:[],student:old?.student||'HS demo'};
storage.save(store);
}
// Preserve V2 browser data, add V3 seed questions without deleting attempts or teacher questions.
if(store&&Array.isArray(store.bank)&&Array.isArray(store.attempts)){
 const current=new Set(store.bank.map(q=>String(q.id)));
 let changed=false;
 for(const q of window.CHEM_MAP_SEED){if(!current.has(String(q.id))){store.bank.push(structuredClone(q));changed=true}}
 if(changed)storage.save(store);
}
let state={coverageGrade:'all',view:'home',setup:{grade:'10',chapter:'all',lesson:'all',count:'5',mode:'diagnostic',level:'all',competency:'all',type:'all'},session:null,result:null,error:'',search:''};
const screen=document.getElementById('screen'),title=document.getElementById('page-title'),nameInput=document.getElementById('student-name');nameInput.value=store.student||'HS demo';
function E(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};
function txt(v){return E(v).replace(/\n/g,'<br>')};function stamp(s){try{return new Date(s).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}catch{return s}};
function safePct(x){return Number.isFinite(x)?Math.min(100,Math.max(0,Math.round(x))):0};function uid(){return 'A'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)};
function attemptRows(){return store.attempts.filter(a=>a.student===store.student)};
function qby(id){return store.bank.find(q=>q.id===id)}
function published(q){return ['sample','approved','published'].includes(q.status)}
function chapterMeta(g){return CAT[String(g)]||[]}
function lessonN(g,c,l){return store.bank.filter(q=>published(q)&&q.grade===Number(g)&&q.chapter===c&&q.lesson===l).length}
function validSource(s){return /^https:\/\//.test(String(s||''))};
function observations(){return attemptRows().flatMap(a=>a.records.filter(r=>r.maxPoints>0).map(r=>({...r,at:a.at,grade:a.grade}))).filter(r=>qby(r.questionId))}
function insight(){const seen=observations(),byTopic={};seen.forEach((r,i)=>{const q=qby(r.questionId);const key=q.grade+'|'+q.chapter;if(!byTopic[key])byTopic[key]={grade:q.grade,chapter:q.chapter,vals:[],errors:[]};byTopic[key].vals.push({score:r.points/r.maxPoints,at:r.at,i});byTopic[key].errors.push(...r.errors)});return Object.values(byTopic).map(t=>{const val=t.vals.slice(-10);let d=0,n=0;val.forEach((v,i)=>{const w=1+i*.15;n+=w*v.score;d+=w});return {...t,samples:t.vals.length,mastery:Math.round(100*n/d)} }).sort((a,b)=>a.mastery-b.mastery)};
function perLessonMap(){const m=new Map();for(const a of attemptRows())for(const r of (a.records||[])){
 if(!(r.maxPoints>0))continue;const q=qby(r.questionId);if(!q)continue;
 const key=q.grade+'|'+q.chapter+'|'+q.lesson;
 if(!m.has(key))m.set(key,[]);m.get(key).push({at:a.at,score:r.points/r.maxPoints});
 }return m}
function lessonPath(g,ci,li){const ch=chapterMeta(g)[ci];return ch?{chapter:ch.name,lesson:ch.lessons[li]}:null}
function openLesson(g,ci,li){const path=lessonPath(g,ci,li);if(!path)return;
 state.setup.grade=String(g);state.setup.chapter=path.chapter;state.setup.lesson=path.lesson;
 state.setup.level='all';state.setup.type='all';state.setup.competency='all';state.setup.mode='practice';
 const count=lessonN(g,path.chapter,path.lesson);state.setup.count=count>=5?'5':String(Math.min(4,count));
 state.session=null;state.result=null;state.view='practice';render();window.scrollTo(0,0)}
function latestStats(){let a=attemptRows(),obs=observations();return {attempts:a.length,answered:obs.length,accuracy:obs.length?Math.round(obs.reduce((s,r)=>s+r.points/r.maxPoints,0)/obs.length*100):null}};
function nav(view){state.view=view;state.session=null;state.result=null;state.error='';document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();window.scrollTo({top:0,behavior:'instant'})}
function head(h){title.textContent=h}
function empty(t,d){return `<div class="empty"><h3>${E(t)}</h3><p>${E(d)}</p></div>`}
function home(){head('Tổng quan học tập');const st=latestStats(),ins=insight().filter(x=>x.grade===Number(state.setup.grade));return `<div class="card hero"><div><div class="kicker" style="color:#9fc5ff">HỌC THEO ĐÚNG NHU CẦU CỦA EM</div><h2>Hiểu bản chất Hóa học, nhận diện lỗi sai và tiến bộ từng ngày.</h2><p>Học sinh chọn lớp, chương, bài; luyện tập theo 4 dạng câu hỏi; nhận giải thích đúng/sai và gợi ý sửa lỗi theo năng lực.</p><button class="btn btn-light" data-action="goto-practice">Bắt đầu luyện tập →</button></div><div class="hero-glyph">H₂O</div></div>
<div class="cards3"><div class="card"><div class="metric">${st.attempts}</div><div class="metric-label">Lượt làm bài đã lưu</div></div><div class="card"><div class="metric">${st.answered}</div><div class="metric-label">Câu đã được chấm tự động</div></div><div class="card"><div class="metric">${st.accuracy===null?'—':st.accuracy+'%'}</div><div class="metric-label">Độ chính xác trung bình*</div></div></div>
<div class="layout-two"><div class="card"><h2>Học như thế nào?</h2><div class="mini-list">${[['01','Chọn đúng nội dung','Lớp 10–12 → Chương → Bài → 5/10/15 câu.'],['02','Làm bài và nhận phản hồi','Xem đáp án, lời giải, phân loại lỗi theo lựa chọn.'],['03','Luyện lại điểm yếu','Chọn chế độ luyện lại, ưu tiên nội dung còn hạn chế.'],['04','Đánh giá sự tiến bộ','Quan sát bản đồ năng lực dựa trên dữ liệu làm bài.']].map(x=>`<div class="mini-item"><div><span class="badge-number">${x[0]}</span> <strong>${x[1]}</strong><small style="margin-left:49px">${x[2]}</small></div></div>`).join('')}</div></div>
<div class="card"><h2>Ưu tiên học tập của em</h2>${ins.length?`<div class="mini-list">${ins.slice(0,4).map(t=>`<div class="mini-item"><div><strong>${E(t.chapter)}</strong><small>${t.samples} lượt được chấm</small></div><span class="chip ${t.mastery<60?'chip-orange':'chip-green'}">${t.mastery}%</span></div>`).join('')}</div><button class="btn btn-soft" data-action="goto-map">Xem bản đồ năng lực</button>`:empty('Chưa có dữ liệu','Hoàn thành một bài luyện tập để nhận đề xuất cá nhân.')}</div></div><p class="subtle">*Độ chính xác chỉ tính các phần được chấm tự động; tự luận chưa được chấm trong bản mẫu.</p>`}
function chooseOptions(values,selected){return values.map(([id,label])=>`<option value="${E(id)}" ${String(selected)===String(id)?'selected':''}>${E(label)}</option>`).join('')}
function filteredSetup(){
const grade=Number(state.setup.grade),chapters=chapterMeta(grade).map(c=>c.name);
const activeChapter=state.setup.chapter;
const available=chapterMeta(grade).filter(c=>activeChapter==='all'||c.name===activeChapter);
const lessons=available.flatMap(c=>c.lessons);
const filtered=store.bank.filter(q=>published(q)&&q.grade===grade&&(activeChapter==='all'||q.chapter===activeChapter)&&(state.setup.lesson==='all'||q.lesson===state.setup.lesson)&&(state.setup.level==='all'||q.level===state.setup.level)&&(state.setup.competency==='all'||q.competency===state.setup.competency)&&(state.setup.type==='all'||q.type===state.setup.type));
return {grade,chapters,lessons,filtered};}

function practice(){head('Luyện tập & kiểm tra');if(state.session)return quiz();if(state.result)return result();
const {chapters,lessons,filtered}=filteredSetup();const available=filtered.length,planned=Number(state.setup.count),emptyLesson=available===0;
const availableByType=['mcq','tf','short','essay'].map(t=>[TYPES[t],filtered.filter(q=>q.type===t).length]);
return `<div class="section-head"><div><h2>Lựa chọn bài học & mục tiêu</h2><p>Đủ 72 bài KNTT 10–12 có câu hỏi mẫu. Mỗi bài có ít nhất 6 câu minh họa, có thể luyện nhanh 5 câu; bài 10–15 câu cần đủ dữ liệu.</p></div><span class="chip chip-green">${store.bank.filter(published).length} câu mẫu · 72/72 bài</span></div>
<div class="layout-two"><div class="card"><div class="form-grid">
<div class="field"><label for="grade">Khối lớp</label><select id="grade" data-setup="grade">${chooseOptions([[10,'Hóa học 10'],[11,'Hóa học 11'],[12,'Hóa học 12']],state.setup.grade)}</select></div>
<div class="field"><label for="mode">Mục tiêu</label><select id="mode" data-setup="mode">${chooseOptions([['diagnostic','Chẩn đoán đầu vào'],['practice','Ôn tập chủ đề'],['remedial','Luyện sửa lỗi sai'],['test','Kiểm tra không gợi ý'],['midterm','Đề giữa kì (mẫu)'],['final','Đề cuối kì (mẫu)'],['transfer','Đánh giá chuyển giao câu mới']],state.setup.mode)}</select></div>
<div class="field full"><label for="chapter">Chương (có đủ tất cả chương)</label><select id="chapter" data-setup="chapter">${chooseOptions([['all','Tất cả các chương'],...chapters.map(c=>[c,c])],state.setup.chapter)}</select></div>
<div class="field full"><label for="lesson">Bài học (đúng tên SGK)</label><select id="lesson" data-setup="lesson">${chooseOptions([['all','Tất cả các bài trong phạm vi'],...lessons.map(l=>[l,l+' · '+lessonN(Number(state.setup.grade),state.setup.chapter==='all'?(chapterMeta(state.setup.grade).find(c=>c.lessons.includes(l))?.name||''):state.setup.chapter,l)+' câu'])],state.setup.lesson)}</select></div>
<div class="field"><label for="level">Mức độ</label><select id="level" data-setup="level">${chooseOptions([['all','Tất cả mức độ'],...Object.entries(LEVELS)],state.setup.level)}</select></div>
<div class="field"><label for="competency">Năng lực</label><select id="competency" data-setup="competency">${chooseOptions([['all','HH1 + HH2 + HH3'],['HH1','HH1 · Nhận thức'],['HH2','HH2 · Tìm hiểu'],['HH3','HH3 · Vận dụng']],state.setup.competency)}</select></div>
<div class="field"><label for="type">Loại câu</label><select id="type" data-setup="type">${chooseOptions([['all','Cả 4 phần Form 2025'],...Object.entries(TYPES)],state.setup.type)}</select></div>
<div class="field"><label for="count">Số lượng</label><select id="count" data-setup="count">${chooseOptions([[3,'3 câu (bài ít câu)'],[4,'4 câu (bài ít câu)'],[5,'5 câu'],[10,'10 câu'],[15,'15 câu']],state.setup.count)}</select></div>
</div><div class="notice ${available<planned?'notice-warning':''}"><b>${available}</b> câu phù hợp · ${availableByType.map(([t,n])=>E(t)+': '+n).join(' · ')}.<br>${emptyLesson?'Chưa có câu ở phạm vi này. Chọn chương/bài khác hoặc bổ sung nguồn câu hỏi.':available<planned?'Chưa đủ số lượng đã chọn; hãy giảm số câu hoặc mở rộng phạm vi.':'Có thể bắt đầu làm bài; hệ thống không lặp mã câu trong một phiên.'}</div>${state.error?`<div class="notice notice-danger">${E(state.error)}</div>`:''}
<div class="button-row"><button class="btn btn-primary" data-action="start" ${available<planned?'disabled':''}>Bắt đầu ${planned} câu →</button><button class="btn btn-outline" data-action="goto-map">Xem bản đồ năng lực</button></div>
</div><div class="card"><h2>PHẦN I–IV · Form 2025</h2><div class="mini-list"><div class="mini-item"><div><b>I. Trắc nghiệm nhiều phương án</b><small>Chọn 1 đáp án.</small></div></div><div class="mini-item"><div><b>II. Đúng / Sai</b><small>4 nhận định a, b, c, d.</small></div></div><div class="mini-item"><div><b>III. Trả lời ngắn</b><small>Nhập số, được tính dung sai.</small></div></div><div class="mini-item"><div><b>IV. Tự luận</b><small>Hướng dẫn chấm, chưa tự cho điểm.</small></div></div></div><div class="notice"><b>Ghi chú quan trọng:</b> Đây là các bài kiểm tra luyện tập tạo từ ngân hàng theo phạm vi chọn. Dù đã có câu ở mọi bài, không được coi là đề kiểm tra chính thức theo ma trận 40–30–30 nếu chưa được giáo viên lập ma trận và duyệt. Bộ ngân hàng có nhiều biến thể tham số cùng dạng.</div><button class="btn btn-soft btn-small" data-action="goto-sources">Xem nguồn và bản quyền</button></div></div>`}


// V4.1: transfer practice deliberately avoids repeating questions from the latest attempt.
// Selection is heuristic by the same lesson / competency, not psychometrically equated.
function transferWrong(){
 const a=state.result;if(!a)return;
 const wrong=a.records.filter(r=>r.maxPoints>0&&r.points<r.maxPoints).map(r=>qby(r.questionId)).filter(Boolean);
 if(!wrong.length){alert('Chưa có câu sai được chấm tự động trong lượt này.');return}
 const excluded=new Set(a.questionIds);const used=new Set(attemptRows().flatMap(v=>v.questionIds||[]));
 let pool=store.bank.filter(q=>published(q)&&q.grade===a.grade&&!excluded.has(q.id)&&wrong.some(t=>t.chapter===q.chapter&&t.lesson===q.lesson));
 if(!pool.length){alert('Chưa có câu tương đương độc lập trong đúng bài này. Hãy mở thêm phạm vi chương hoặc bổ sung câu đã kiểm duyệt.');return}
 const rank=q=>{const nearest=wrong.filter(t=>t.lesson===q.lesson&&t.chapter===q.chapter);return (used.has(q.id)?0:5)+(nearest.some(t=>t.competency===q.competency)?6:0)+(nearest.some(t=>t.level===q.level)?2:0)+(nearest.some(t=>t.type===q.type)?1:0)+(q.sourceId==='CURATED_V4'?1:0)};
 pool.sort((a,b)=>rank(b)-rank(a)||String(a.id).localeCompare(String(b.id)));
 const wanted=Math.min(10,Math.max(5,wrong.length*2));const qs=pool.slice(0,wanted);
 state.setup.grade=String(a.grade);state.setup.chapter='all';state.setup.lesson='all';state.setup.mode='transfer';state.setup.count=String(qs.length);
 state.session={questions:qs,step:0,answers:{},seenHint:{},startedAt:new Date().toISOString(),transferFrom:a.id};state.result=null;state.view='practice';render();window.scrollTo(0,0)
}

function retryWrong(){const a=state.result;if(!a)return;
 const ids=a.records.filter(r=>r.maxPoints>0&&r.points<r.maxPoints).map(r=>r.questionId);
 const qs=ids.map(qby).filter(q=>q&&published(q));
 if(!qs.length){alert('Không có câu tự động chấm sai trong lượt này.');return}
 state.setup.grade=String(a.grade);state.setup.mode='remedial';
 state.session={questions:qs,step:0,answers:{},seenHint:{},startedAt:new Date().toISOString()};
 state.result=null;state.view='practice';render();window.scrollTo(0,0);
}
function start(){const {filtered}=filteredSetup();let cnt=Number(state.setup.count);if(filtered.length<cnt){state.error='Không đủ câu hỏi theo phạm vi. Hãy chọn tất cả chương hoặc nhập thêm câu.';return render()}let qs=[...filtered];if(state.setup.mode==='remedial'){const levels=insight();qs.sort((a,b)=>{const aa=levels.find(x=>x.grade===a.grade&&x.chapter===a.chapter);const bb=levels.find(x=>x.grade===b.grade&&x.chapter===b.chapter);return (aa?.mastery??50)-(bb?.mastery??50)||Math.random()-.5})}else{qs.sort(()=>Math.random()-.5)};qs=qs.slice(0,cnt);qs.sort((a,b)=>['mcq','tf','short','essay'].indexOf(a.type)-['mcq','tf','short','essay'].indexOf(b.type));state.session={questions:qs,step:0,answers:{},seenHint:{},startedAt:new Date().toISOString()};state.result=null;state.error='';render()}
function isAnswered(q,v){if(q.type==='tf')return Array.isArray(v)&&v.length===4&&v.every(x=>x==='T'||x==='F');return v!==undefined&&v!==null&&String(v).trim()!==''}
function quiz(){const s=state.session,q=s.questions[s.step],ans=s.answers[q.id],done=s.questions.filter(a=>isAnswered(a,s.answers[a.id])).length,pc=Math.round(done/s.questions.length*100);head('Đang làm bài · Hóa học '+state.setup.grade);let body='';if(q.type==='mcq'){body=q.options.map((o,i)=>`<label class="radio-line"><input type="radio" name="mcq" value="${i}" ${ans===i?'checked':''}><span class="letter">${'ABCD'[i]}.</span><span>${txt(o)}</span></label>`).join('')}else if(q.type==='tf'){body=q.statements.map((t,i)=>`<div class="tf-row"><div><strong>${'abcd'[i]})</strong> ${txt(t)}</div><label><input name="tf${i}" type="radio" value="T" ${ans?.[i]==='T'?'checked':''}> Đúng</label><label><input name="tf${i}" type="radio" value="F" ${ans?.[i]==='F'?'checked':''}> Sai</label></div>`).join('')}else if(q.type==='short'){body=`<div class="field"><label for="short-answer">Kết quả (nhập số, dấu thập phân . hoặc ,)</label><input id="short-answer" inputmode="decimal" type="text" value="${E(ans??'')}" placeholder="Ví dụ: 0,25"><small class="muted">${q.unit?'Đơn vị kết quả: '+E(q.unit):'Chỉ nhập số, không cần đơn vị.'}</small></div>`}else{body=`<div class="field"><label for="essay-answer">Trình bày lập luận và phương trình hóa học (nếu có)</label><textarea rows="8" id="essay-answer" placeholder="Viết lời giải của em...">${E(ans??'')}</textarea><small class="muted">Tự luận sẽ lưu bài làm, chưa tính vào độ chính xác tự động.</small></div>`}
const hint=state.setup.mode==='test'?'':`<button class="btn btn-outline btn-small" data-action="hint">${s.seenHint[q.id]?'Ẩn':'Xem'} gợi ý</button>`;
return `<div class="card"><div class="quiz-top"><span class="chip">Câu ${s.step+1}/${s.questions.length} · ${E(q.grade)} · ${E(q.level)} · ${E(q.competency)}</span><span class="q-type">${E(TYPES[q.type])}</span></div><div style="margin:15px 0 0" class="progress"><span style="width:${pc}%"></span></div><div class="quiz-stem">${txt(q.stem)}</div>${body}${s.seenHint[q.id]?`<div class="notice">Gợi ý: ${txt(q.hint||'Hãy chia bài toán thành từng bước.')}</div>`:''}<div class="q-footer"><div class="button-row">${hint}<button class="btn btn-outline btn-small" data-action="back-setup">Thoát phiên</button></div><div class="button-row"><button class="btn btn-outline" data-action="prev" ${s.step===0?'disabled':''}>← Trước</button>${s.step===s.questions.length-1?'<button class="btn btn-primary" data-action="submit">Nộp bài & nhận phân tích</button>':'<button class="btn btn-primary" data-action="next">Tiếp →</button>'}</div></div><div class="subtle" style="margin-top:12px">Đã trả lời ${done}/${s.questions.length} câu. Có thể quay lại sửa trước khi nộp.</div></div>`}
function normalizeNum(input){if(typeof input==='number')return input;if(typeof input!=='string')return NaN;const s=input.trim().replace(/\s+/g,'').replace(',','.').replace(/^\+/,'');if(!/^-?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))return NaN;return Number(s)}
function gradeQ(q,selected){if(q.type==='mcq'){let correct=selected===q.answer,err=!correct?[q.misconceptions?.[String(selected)]||'Chưa nắm chính xác kiến thức trọng tâm.']:[];return {points:correct?1:0,maxPoints:1,errors:err}}if(q.type==='tf'){let points=0,errs=[];q.answer.forEach((v,i)=>{if((selected?.[i]==='T')===v&&selected?.[i])points+=.25;else errs.push(`Ý ${'abcd'[i]}: cần đối chiếu lại nhận định với bản chất Hóa học.`)});return {points,maxPoints:1,errors:errs}}if(q.type==='short'){let value=normalizeNum(selected),good=Number.isFinite(value)&&Math.abs(value-q.answer)<=Number(q.tolerance??0);return {points:good?1:0,maxPoints:1,errors:good?[]:['Kiểm tra công thức, phép tính, đơn vị và chữ số kết quả.']}}return {points:0,maxPoints:0,errors:[]}}
function submit(){const s=state.session;if(!s)return;let unanswered=s.questions.filter(q=>!isAnswered(q,s.answers[q.id]));if(unanswered.length&&!confirm(`Còn ${unanswered.length} câu chưa hoàn thành. Vẫn nộp bài?`))return;const records=s.questions.map(q=>{let sel=s.answers[q.id];return {questionId:q.id,selected:sel??null,...gradeQ(q,sel)}});const auto=records.filter(x=>x.maxPoints>0),score=auto.reduce((n,r)=>n+r.points,0),percent=auto.length?Math.round(score/auto.length*100):null;const result={transferFrom:s.transferFrom||null,id:uid(),at:new Date().toISOString(),student:store.student,grade:Number(state.setup.grade),chapter:state.setup.chapter,lesson:state.setup.lesson,mode:state.setup.mode,questionIds:s.questions.map(q=>q.id),records,score,maxScore:auto.length,accuracy:percent,pendingEssay:records.filter(x=>qby(x.questionId)?.type==='essay').length};store.attempts.push(result);storage.save(store);state.result=result;state.session=null;render()}
function answerView(q,answer){if(q.type==='mcq')return answer===undefined||answer===null?'Chưa trả lời':('ABCD'[answer]||'Không hợp lệ');if(q.type==='tf')return Array.isArray(answer)?answer.map(x=>x==='T'?'Đ':x==='F'?'S':'–').join(' · '):'Chưa trả lời';return answer===undefined||answer===null?'Chưa trả lời':String(answer)};
function rightView(q){if(q.type==='mcq')return `${'ABCD'[q.answer]}. ${q.options[q.answer]}`;if(q.type==='tf')return q.answer.map(x=>x?'Đ':'S').join(' · ');if(q.type==='short')return `${q.answer}${q.unit?' '+q.unit:''}`;return 'Lời giải tham khảo / rubric do giáo viên duyệt'}
function result(){let a=state.result;head('Kết quả & phân tích lỗi sai');const wrong=a.records.filter(x=>x.maxPoints>0&&x.points<x.maxPoints),label=a.accuracy===null?'Chưa có điểm':a.accuracy+'%',topics=[...new Set(wrong.map(x=>qby(x.questionId)?.chapter).filter(Boolean))];return `<div class="card"><div class="section-head"><div><div class="kicker">KẾT QUẢ LẦN LUYỆN</div><h2 class="result-h">${label} · ${a.score.toFixed(2).replace(/\.00$/,'')} / ${a.maxScore} điểm tự động</h2><p>${E(a.student)} · ${stamp(a.at)} · Hóa học ${a.grade}</p></div><div class="badge-number">${wrong.length} câu cần ôn lại</div></div><div class="cards3" style="margin-top:10px"><div><div class="metric">${a.questionIds.length}</div><span class="metric-label">Tổng câu trong phiên</span></div><div><div class="metric">${wrong.length}</div><span class="metric-label">Câu tự động chưa đạt tối đa</span></div><div><div class="metric">${a.pendingEssay}</div><span class="metric-label">Câu tự luận chờ đánh giá</span></div></div><div class="competency-line">${['HH1','HH2','HH3'].map(k=>{const rows=a.records.filter(r=>r.maxPoints>0&&qby(r.questionId)?.competency===k);const den=rows.reduce((s,r)=>s+r.maxPoints,0);const num=rows.reduce((s,r)=>s+r.points,0);return `<span class="chip">${k}: ${den?Math.round(num/den*100)+'%':'chưa đo'}</span>`}).join('')}</div>${a.transferFrom?'<div class="notice"><b>Bài luyện chuyển giao:</b> Những câu hỏi khác mã so với bài trước và cùng bài/chủ đề. Chưa hiệu chỉnh độ khó, không dùng phần trăm thay đổi như chứng cứ hiệu quả chính thức.</div>':''}<div class="divider"></div><div class="callout"><strong>Gợi ý lộ trình cá nhân</strong><p style="margin:7px 0 0">${topics.length?`Ưu tiên ôn: ${topics.map(E).join('; ')}. Xem từng lỗi bên dưới, sau đó chọn <strong>Luyện lại điểm yếu</strong>.`:'Chưa phát hiện lỗi ở phần tự động. Hãy luyện tiếp ở mức độ khó hơn và hoàn thiện phần tự luận.'} Đề xuất này dựa trên lịch sử lựa chọn đáp án, không phải suy luận AI tạo sinh.</p></div><div class="button-row" style="margin-top:16px"><button class="btn btn-primary" data-action="new-quiz">Làm phiên mới</button>${wrong.length?`<button class="btn btn-soft" data-action="retry-wrong">Ôn lại ${wrong.length} câu sai</button><button class="btn btn-primary" data-action="transfer-wrong">Luyện câu mới cùng chủ đề →</button>`:''}<button class="btn btn-outline" data-action="print-result">In lời giải</button><button class="btn btn-outline" data-action="goto-map">Bản đồ năng lực</button></div></div>
<div class="section-head"><div><h2>Giải thích chi tiết từng câu</h2><p>Mỗi phản hồi có đáp án chuẩn và minh chứng kiến thức để học sinh tự sửa sai.</p></div></div>${a.records.map((r,i)=>{const q=qby(r.questionId);if(!q)return '';let good=r.maxPoints===0?'pending':r.points===r.maxPoints?'correct':'wrong';return `<div class="answer-card ${good}"><strong>Câu ${i+1} · ${E(q.chapter)} <span class="tag">${E(q.level)}</span> <span class="tag">${E(q.competency)}</span></strong><div>${txt(q.stem)}</div><p><b>Em trả lời:</b> ${txt(answerView(q,r.selected))} &nbsp; | &nbsp; <b>Đáp án:</b> ${txt(rightView(q))}</p><p><b>Giải thích:</b> ${txt(q.explanation)}</p>${r.errors.length?`<p style="color:#a44d45"><b>Phân tích lỗi:</b> ${r.errors.map(txt).join(' ')}</p>`:''}${validSource(q.referenceUrl)?`<p class="subtle"><b>Đọc thêm:</b> <a href="${E(q.referenceUrl)}" target="_blank" rel="noopener noreferrer">Tài liệu nền cho chủ đề</a> (không phải câu hỏi sao chép)</p>`:''}${q.type==='essay'?`<p><b>Hướng dẫn tham khảo:</b> ${txt(q.sampleAnswer)}</p><p><b>Tiêu chí chấm:</b> ${q.rubric.map(x=>txt(typeof x==='string'?x:(x.criterion||'')+' ('+(x.points??'?')+' điểm)')).join(' · ')}</p>`:''}</div>`}).join('')}`}
function skillMap(){head('Bản đồ năng lực');let all=insight(),inGrade=all.filter(x=>x.grade===Number(state.setup.grade));const chapters=chapterMeta(Number(state.setup.grade)).map(c=>c.name);return `<div class="section-head"><div><h2>Độ thành thạo theo chương</h2><p>Đánh giá dựa trên các câu được chấm tự động, ưu tiên dữ liệu gần đây. Chưa đủ 3 quan sát: không kết luận thành thạo.</p></div><div><select id="map-grade" class="search-bar">${chooseOptions([[10,'Hóa học 10'],[11,'Hóa học 11'],[12,'Hóa học 12']],state.setup.grade)}</select></div></div><div class="layout-two"><div class="card"><h2>CHEM-MAP · ${E(state.setup.grade)}</h2>${chapters.map(ch=>{const t=inGrade.find(x=>x.chapter===ch),v=t?.mastery??0,st=!t||t.samples<3?'Chưa đủ dữ liệu':v>=80?'Vững':v>=60?'Đang tiến bộ':'Cần củng cố',cls=!t||t.samples<3?'warn':v>=80?'good':v>=60?'warn':'low';return `<div class="topic-row"><div><strong>${E(ch)}</strong><small>${t?t.samples+' câu được chấm':'Chưa luyện tập'} · ${store.bank.filter(q=>published(q)&&q.chapter===ch&&q.grade===Number(state.setup.grade)).length} câu trong ngân hàng</small></div><div class="progress"><span style="width:${t?v:0}%"></span></div><div class="status ${cls}">${t?v+'%':'—'}<small>${st}</small></div></div>`}).join('')}</div><div class="card"><h2>Cách đọc bản đồ</h2><p>Điểm hiển thị là tỉ lệ câu đúng có trọng số gần đây, <strong>không phải</strong> kết luận chính thức về năng lực học sinh.</p><div class="mini-list"><div class="mini-item"><span class="chip chip-green">80–100%</span><small>Có dấu hiệu nắm vững khi đủ dữ liệu</small></div><div class="mini-item"><span class="chip">60–79%</span><small>Tiếp tục luyện tập có mục tiêu</small></div><div class="mini-item"><span class="chip chip-orange">0–59%</span><small>Ưu tiên sửa lỗi, ôn lại kiến thức gốc</small></div><div class="mini-item"><span class="chip">Dưới 3 câu</span><small>Chưa đủ dữ liệu để đánh giá</small></div></div><div class="notice">Khi phát triển bản chính thức, cần chuẩn hóa độ khó, tính tin cậy và kiểm định đánh giá trước khi dùng cho quyết định giáo dục.</div><button class="btn btn-primary" data-action="goto-practice">Luyện lại điểm yếu</button></div></div>`}
function history(){head('Lịch sử học tập');const hist=[...attemptRows()].reverse();return `<div class="section-head"><div><h2>Hành trình tiến bộ</h2><p>Dữ liệu theo tên hiển thị trong trình duyệt hiện tại; chưa đồng bộ giữa các thiết bị.</p></div><button class="btn btn-outline btn-small" data-action="export-csv">Xuất báo cáo CSV</button></div><div class="card">${hist.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Thời điểm</th><th>Lớp</th><th>Mục tiêu</th><th>Số câu</th><th>Điểm tự động</th><th>Tự luận</th><th>Thao tác</th></tr></thead><tbody>${hist.map(a=>`<tr><td>${stamp(a.at)}</td><td>${a.grade}</td><td>${E(a.mode)}</td><td>${a.questionIds.length}</td><td>${a.accuracy??'—'}%</td><td>${a.pendingEssay} chờ chấm</td><td><button class="btn btn-soft btn-small" data-open-attempt="${E(a.id)}">Xem lại</button></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có lịch sử','Hãy hoàn thành một phiên học để xem lại lời giải và tiến bộ.')}</div>`}
function sources(){head('Nguồn câu hỏi & bản quyền');
const gradeStat=[10,11,12].map(g=>({g,all:store.bank.filter(q=>q.grade===g).length,ok:store.bank.filter(q=>q.grade===g&&published(q)).length,chs:chapterMeta(g).length}));
return `<div class="card"><div class="kicker">NGÂN HÀNG CÂU HỎI V4.1</div><h2>Minh bạch nguồn và mức độ bao phủ</h2><p>Câu hỏi mới được biên soạn độc lập bằng tiếng Việt, kết hợp tham khảo kiến thức phổ thông, cấu trúc nội dung từ nguồn mở. Không phải bản sao toàn bộ ngân hàng câu hỏi của các website.</p><div class="cards3">${gradeStat.map(x=>`<div class="stat-mini"><b>Hóa ${x.g}</b><strong>${x.ok} câu</strong><small>${x.chs} chương · đã có câu ở mọi bài</small></div>`).join('')}</div><div class="notice notice-warning"><b>Quyền sử dụng:</b> Các liên kết là nguồn tham khảo ngoài. Không phân phối lại bài tập/ảnh/mô phỏng của website nếu chưa phù hợp giấy phép. OpenStax có điều kiện riêng về đưa nội dung vào sản phẩm AI; PhET có giới hạn sử dụng thương mại.</div></div><div class="card"><h2>Danh mục nguồn truy xuất được</h2><div class="source-grid">${SOURCES.map(x=>`<article class="source-card"><strong>${E(x.name)}</strong><div class="subtle">${E(x.license)}</div><p>${E(x.usage)}</p>${validSource(x.url)?`<a href="${E(x.url)}" target="_blank" rel="noopener noreferrer">Mở nguồn tham khảo ↗</a>`:''}</article>`).join('')}</div></div><div class="card"><h2>Quy trình giáo viên kiểm duyệt</h2><p>Thêm nguồn → đối chiếu bài/chương → kiểm tra công thức và số liệu → kiểm tra đáp án → phân loại HH1–HH3, nhận biết/thông hiểu/vận dụng/vận dụng cao → duyệt xuất bản.</p><p class="subtle">Hệ thống hiện có bộ phân tích lỗi theo quy tắc; chưa truy cập các website theo thời gian thực và chưa có AI tự sinh đáp án từ nội dung bên ngoài.</p></div>`}
function teacher(){head('Góc giáo viên · Ngân hàng câu hỏi');const stat={total:store.bank.length,byGrade:[10,11,12].map(g=>store.bank.filter(q=>q.grade===g).length),attempts:store.attempts.length},bank=store.bank.filter(q=>(q.id+' '+q.chapter+' '+q.lesson+' '+(q.sourceId||'')+' '+q.stem).toLowerCase().includes(state.search.toLowerCase()));return `<div class="notice notice-warning top-alert"><strong>Lưu ý quyền truy cập:</strong> Góc giáo viên hiện là giao diện DEMO, <strong>không có đăng nhập/phân quyền thật</strong>; dữ liệu chỉ nằm trong trình duyệt. Không nhập thông tin hoặc bài làm thật của học sinh ở bản này.</div><div class="cards3"><div class="card"><div class="metric">${stat.total}</div><div class="metric-label">Câu hỏi hiện có</div></div><div class="card"><div class="metric">${stat.byGrade.join(' / ')}</div><div class="metric-label">Lớp 10 / 11 / 12</div></div><div class="card"><div class="metric">${stat.attempts}</div><div class="metric-label">Phiên làm bài lưu cục bộ</div></div></div><div class="layout-two"><div class="card"><h2>Cập nhật ngân hàng câu hỏi</h2><p>Nhập tệp JSON hoặc CSV (chỉ trắc nghiệm cho CSV) theo mẫu. Hệ thống kiểm tra các trường bắt buộc, ID và đáp án trước khi thêm.</p><div class="button-row"><label class="file-picker"><input id="import-json" type="file" accept=".json,.csv,application/json,text/csv" aria-label="Chọn tệp câu hỏi JSON"></label><button class="btn btn-outline btn-small" data-action="export-bank">Xuất ngân hàng JSON</button><button class="btn btn-soft btn-small" data-action="download-template">Tải CSV mẫu</button></div><div class="divider"></div><h3>Thêm nhanh câu trắc nghiệm</h3><div class="form-grid"><div class="field"><label for="new-grade">Lớp</label><select id="new-grade"><option>10</option><option>11</option><option>12</option></select></div><div class="field"><label for="new-level">Mức độ</label><select id="new-level">${chooseOptions(Object.entries(LEVELS),'TH')}</select></div><div class="field"><label for="new-chapter">Chương</label><input id="new-chapter" placeholder="Ví dụ: Cấu tạo nguyên tử"></div><div class="field"><label for="new-lesson">Bài</label><input id="new-lesson" placeholder="Ví dụ: Cấu hình electron"></div><div class="field full"><label for="new-stem">Nội dung câu hỏi</label><textarea id="new-stem" rows="2"></textarea></div>${['A','B','C','D'].map((k,i)=>`<div class="field"><label for="new-o${i}">Đáp án ${k}</label><input id="new-o${i}"></div>`).join('')}<div class="field"><label for="new-answer">Đáp án đúng</label><select id="new-answer">${chooseOptions([[0,'A'],[1,'B'],[2,'C'],[3,'D']],0)}</select></div><div class="field"><label for="new-comp">Năng lực</label><select id="new-comp">${chooseOptions([['HH1','HH1 - Nhận thức'],['HH2','HH2 - Tìm hiểu tự nhiên'],['HH3','HH3 - Vận dụng']], 'HH1')}</select></div><div class="field full"><label for="new-explain">Lời giải / giải thích</label><textarea id="new-explain" rows="2"></textarea></div></div><button class="btn btn-primary" data-action="add-mcq">Thêm câu trắc nghiệm</button></div><div class="card"><h2>Quản trị chất lượng câu hỏi</h2><ul class="compact"><li>Định danh duy nhất; lớp, chương, bài, loại câu, mức độ và năng lực HH1–HH3.</li><li>Đáp án phải khớp loại câu hỏi; có lời giải đã được kiểm duyệt.</li><li>Câu mới nhập ở trạng thái nháp; cần bấm Duyệt để dùng luyện tập; khi triển khai thật cần quy trình <b>nháp → phản biện → duyệt → phát hành</b>.</li><li>Câu tự luận phải có rubric và cơ chế chấm bởi giáo viên.</li><li>Tách ngân hàng chính thức khỏi câu do AI gợi ý, kiểm định dấu hóa học và phép tính.</li></ul><div class="notice">Danh mục hiển thị 72 bài Hóa học 10–12; các bản ghi là câu mẫu hoặc tham số chờ thẩm định, chưa đủ điều kiện thay thế ngân hàng đề chính thức.</div><button class="btn btn-outline btn-small" data-action="export-csv">Xuất dữ liệu buổi làm</button><button class="btn btn-danger btn-small" data-action="reset" style="margin-top:8px">Xóa dữ liệu demo & khôi phục</button></div></div><div class="card"><div class="section-head"><div><h2>Danh sách câu hỏi</h2><p>Tra cứu, đối chiếu nội dung sau khi cập nhật. Hiển thị 100 câu. Tìm cả tên bài, mã và nguồn.</p></div><input class="search-bar" id="search-bank" style="max-width:275px" value="${E(state.search)}" placeholder="Tìm mã, chương, nội dung"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mã</th><th>Lớp</th><th>Chương / bài</th><th>Loại</th><th>Mức độ</th><th>Trạng thái</th><th>Câu hỏi / nguồn</th></tr></thead><tbody>${bank.slice(0,100).map(q=>`<tr><td><code>${E(q.id)}</code></td><td>${q.grade}</td><td>${E(q.chapter)}<small class="muted" style="display:block">${E(q.lesson)}</small></td><td>${E(TYPES[q.type])}</td><td>${E(q.level)} / ${E(q.competency)}</td><td>${q.status==='sample'?'<span class="chip chip-orange">Mẫu · chờ GV thẩm định</span>':published(q)?'<span class="chip chip-green">Đã duyệt</span>':`<button class="btn btn-soft btn-small" data-approve-id="${E(q.id)}">Duyệt</button>`}</td><td>${txt(q.stem)}<small class="subtle" style="display:block">${E(q.sourceId||'Tự biên soạn')}</small></td></tr>`).join('')}</tbody></table></div></div>`}

function learningPlan(){head('Lộ trình cá nhân hóa');
const m=perLessonMap(),rows=[];for(const g of [10,11,12])chapterMeta(g).forEach((ch,ci)=>ch.lessons.forEach((l,li)=>{
 const obs=m.get(g+'|'+ch.name+'|'+l)||[];const recent=obs.slice(-8);
 const pct=recent.length?Math.round(100*recent.reduce((a,b)=>a+b.score,0)/recent.length):null;
 rows.push({g,ci,li,chapter:ch.name,lesson:l,n:obs.length,pct,available:lessonN(g,ch.name,l)});
}));const needs=rows.filter(x=>x.n>0).sort((a,b)=>(a.pct??101)-(b.pct??101));
const unseen=rows.filter(x=>x.n===0&&x.available>0&&x.g===Number(state.setup.grade)).slice(0,5);
return `<div class="section-head"><div><h2>Gợi ý kế hoạch tự học</h2><p>Quy tắc: ưu tiên bài có tỉ lệ đúng thấp, sau đó đến bài chưa luyện. Không phải đánh giá tâm lý hay suy luận AI tạo sinh.</p></div></div>
<div class="cards3"><div class="card"><div class="metric">${needs.length}</div><div class="metric-label">Bài đã có quan sát</div></div><div class="card"><div class="metric">${needs.filter(x=>x.n>=3&&x.pct<60).length}</div><div class="metric-label">Bài nên ôn lại (≥3 lượt, &lt;60%)</div></div><div class="card"><div class="metric">${rows.length-needs.length}</div><div class="metric-label">Bài chưa có dữ liệu</div></div></div>
<div class="layout-two"><div class="card"><h2>Ưu tiên sửa lỗi</h2>${needs.length?needs.slice(0,12).map(x=>`<div class="mini-item"><div><strong>Hóa ${x.g} · ${E(x.lesson)}</strong><small>${E(x.chapter)} · ${x.n} câu đã chấm · ${x.n<3?'Chưa đủ 3 lượt để kết luận':'Có đủ dữ liệu sơ bộ'}</small></div><div class="plan-actions"><span class="chip ${x.pct<60?'chip-orange':'chip-green'}">${x.pct}%</span><button class="btn btn-outline btn-small" data-open-lesson="${x.g}|${x.ci}|${x.li}">Luyện</button></div></div>`).join(''):empty('Chưa có dữ liệu','Hãy làm một bài kiểm tra chẩn đoán đầu vào.')}</div>
<div class="card"><h2>Gợi ý khám phá bài chưa luyện · Hóa ${E(state.setup.grade)}</h2>${unseen.map(x=>`<div class="mini-item"><div><strong>${E(x.lesson)}</strong><small>${x.available} câu hiện có</small></div><button class="btn btn-outline btn-small" data-open-lesson="${x.g}|${x.ci}|${x.li}">Học ngay</button></div>`).join('')||empty('Đã trải nghiệm nhiều bài','Chọn lớp khác hoặc xem bản đồ năng lực.')}
<div class="notice"><b>Quy tắc kiểm chứng:</b> Hai lần đúng liên tiếp trên cùng một câu không tương đương nắm vững cả chương. Cần kết hợp câu hỏi khác dạng và đánh giá của giáo viên.</div></div></div>`}
function coverage(){head('Độ phủ & kiểm duyệt ngân hàng');const g=state.coverageGrade;
const all=[];for(const grade of [10,11,12]){chapterMeta(grade).forEach((ch,ci)=>ch.lessons.forEach((l,li)=>{
 const qs=store.bank.filter(q=>q.grade===grade&&q.chapter===ch.name&&q.lesson===l);
 all.push({grade,ci,li,chapter:ch.name,lesson:l,count:qs.filter(published).length,review:qs.filter(q=>q.status==='draft').length,
 levels:new Set(qs.filter(published).map(q=>q.level)).size,
 types:new Set(qs.filter(published).map(q=>q.type)).size,hh2:qs.filter(q=>published(q)&&q.competency==='HH2').length,hh3:qs.filter(q=>published(q)&&q.competency==='HH3').length});
 }))}const rows=all.filter(x=>g==='all'||String(x.grade)===g);
const under=rows.filter(x=>x.count<5).length,zero=rows.filter(x=>x.count===0).length;
return `<div class="section-head"><div><h2>Kiểm soát độ phủ theo từng bài</h2><p>Mỗi bài cần có đủ dạng câu, mức độ và năng lực. Có câu chưa đồng nghĩa đạt chuẩn ma trận kiểm tra.</p></div><select id="coverage-grade" class="search-bar" style="max-width:175px">${chooseOptions([['all','Tất cả lớp'],['10','Hóa 10'],['11','Hóa 11'],['12','Hóa 12']],g)}</select></div>
<div class="cards3"><div class="card"><div class="metric">${rows.length}</div><div class="metric-label">Bài học</div></div><div class="card"><div class="metric">${zero}</div><div class="metric-label">Bài chưa có câu</div></div><div class="card"><div class="metric">${under}</div><div class="metric-label">Bài dưới 5 câu (cần phát triển thêm)</div></div></div>
<div class="card"><div class="button-row"><button class="btn btn-outline btn-small" data-action="export-coverage">Tải báo cáo độ phủ CSV</button><button class="btn btn-outline btn-small" data-action="export-backup">Sao lưu toàn bộ dữ liệu</button><label class="file-picker btn btn-outline btn-small">Khôi phục tệp sao lưu <input id="import-backup" type="file" accept=".json,application/json"></label></div><p class="subtle">Sao lưu phục vụ chuyển máy; file có thể chứa bài làm và tên hiển thị, cần giữ an toàn.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Lớp</th><th>Chương / bài</th><th>Câu dùng thử</th><th>Mức độ / dạng</th><th>HH2 / HH3</th><th>Chờ duyệt</th><th>Thao tác</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.grade}</td><td><b>${E(r.lesson)}</b><small class="subtle" style="display:block">${E(r.chapter)}</small></td><td><span class="chip ${r.count<5?'chip-orange':'chip-green'}">${r.count}</span></td><td>${r.levels} mức · ${r.types} dạng</td><td>${r.hh2} / ${r.hh3}</td><td>${r.review}</td><td><button class="btn btn-outline btn-small" data-open-lesson="${r.grade}|${r.ci}|${r.li}">Mở bài</button></td></tr>`).join('')}</tbody></table></div></div>`}
function exportCoverage(){const rows=[['Lớp','Chương','Bài','Câu được dùng','Câu chờ duyệt','Độ phủ mức độ','Độ phủ dạng câu','HH2','HH3']];
for(const g of [10,11,12])for(const ch of chapterMeta(g))for(const lesson of ch.lessons){const qs=store.bank.filter(q=>q.grade===g&&q.chapter===ch.name&&q.lesson===lesson),ok=qs.filter(published);rows.push([g,ch.name,lesson,ok.length,qs.length-ok.length,new Set(ok.map(q=>q.level)).size,new Set(ok.map(q=>q.type)).size,ok.filter(q=>q.competency==='HH2').length,ok.filter(q=>q.competency==='HH3').length])}
 const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');exportFile('CHEM_MAP_V3_do_phu.csv',csv,'text/csv;charset=utf-8')}
function exportBackup(){exportFile('CHEM_MAP_V3_sao_luu_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({app:'CHEM-MAP V3',version:3,exportedAt:new Date().toISOString(),data:store},null,2),'application/json;charset=utf-8')}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{
 const obj=JSON.parse(String(reader.result)),d=obj.data;
 if(obj.app!=='CHEM-MAP V3'||!d||!Array.isArray(d.bank)||!Array.isArray(d.attempts))throw Error('Không phải tệp sao lưu đúng định dạng V3.');
 if(d.bank.length>15000||d.attempts.length>100000)throw Error('Dữ liệu quá lớn');
 const seen=new Set();for(const q of d.bank){const err=validate(q,seen);if(err)throw Error(q.id+': '+err);seen.add(String(q.id));}
 for(const a of d.attempts)if(!a||!Array.isArray(a.records)||typeof a.student!=='string')throw Error('Lịch sử không hợp lệ');
 if(!confirm('Khôi phục sẽ thay dữ liệu hiện tại trên trình duyệt này. Bạn đã sao lưu dữ liệu đang dùng chưa?'))return;
 store={bank:d.bank,attempts:d.attempts,student:String(d.student||'HS demo').slice(0,28)};
 const ids=new Set(store.bank.map(q=>String(q.id)));for(const q of window.CHEM_MAP_SEED)if(!ids.has(q.id))store.bank.push(structuredClone(q));
 storage.save(store);nameInput.value=store.student;nav('home');alert('Đã khôi phục dữ liệu thành công.')
 }catch(e){alert('Khôi phục thất bại: '+e.message)}};reader.readAsText(file,'utf-8')}

function validate(q,known){if(!q||typeof q!=='object')return 'Bản ghi không hợp lệ';for(const k of ['id','grade','chapter','lesson','type','level','competency','stem','explanation'])if(q[k]===undefined||q[k]===null||q[k]==='')return `Thiếu trường ${k}`;if(known.has(String(q.id)))return `Trùng mã ${q.id}`;if(String(q.stem).length>4500||String(q.explanation).length>7000)return 'Văn bản quá dài';if(![10,11,12].includes(Number(q.grade)))return 'Khối lớp không hợp lệ';if(!TYPES[q.type])return 'Loại câu không hỗ trợ';if(!LEVELS[q.level]||!['HH1','HH2','HH3'].includes(q.competency))return 'Mức độ / năng lực không hợp lệ';if(q.type==='mcq'&&(!Array.isArray(q.options)||q.options.length!==4||!q.options.every(x=>typeof x==='string'&&x.trim())||!Number.isInteger(q.answer)||q.answer<0||q.answer>3))return 'MCQ cần 4 lựa chọn và chỉ số đáp án 0–3';if(q.type==='tf'&&(!Array.isArray(q.statements)||q.statements.length!==4||!Array.isArray(q.answer)||q.answer.length!==4||!q.answer.every(a=>typeof a==='boolean')))return 'Đúng/Sai cần 4 phát biểu và 4 đáp án boolean';if(q.type==='short'&&(!Number.isFinite(q.answer)||(!Number.isFinite(Number(q.tolerance??0))||Number(q.tolerance??0)<0)))return 'Trả lời ngắn cần đáp án số, dung sai hợp lệ';if(q.type==='essay'&&(!q.sampleAnswer||!Array.isArray(q.rubric)))return 'Tự luận cần bài làm tham khảo và rubric';return null}
function exportFile(filename,contents,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([contents],{type:mime}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const rows=[['Mã phiên','Học sinh (demo)','Thời điểm','Lớp','Chương','Bài','Mã câu','Điểm','Điểm tối đa','Nhóm lỗi']];store.attempts.forEach(a=>a.records.forEach(r=>rows.push([a.id,a.student,a.at,a.grade,a.chapter,a.lesson,r.questionId,r.points,r.maxPoints,r.errors.join(' | ')])));const s='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');exportFile('CHEM_MAP_bao_cao_demo.csv',s,'text/csv;charset=utf-8')}
function addMcq(){const get=id=>(document.getElementById(id)?.value||'').trim(),q={id:'USER-'+Date.now(),grade:Number(get('new-grade')),chapter:get('new-chapter'),lesson:get('new-lesson'),topic:get('new-lesson'),type:'mcq',level:get('new-level'),competency:get('new-comp'),stem:get('new-stem'),options:[0,1,2,3].map(i=>get('new-o'+i)),answer:Number(get('new-answer')),explanation:get('new-explain'),hint:'Xác định bản chất Hóa học trước khi chọn đáp án.',version:1,status:'draft',misconceptions:{}};const err=validate(q,new Set(store.bank.map(x=>x.id)));if(err)return alert('Không thêm được: '+err);store.bank.push(q);storage.save(store);alert('Đã thêm câu '+q.id+' ở trạng thái nháp; bấm Duyệt trong danh sách để dùng luyện tập.');render()}
function csvParse(text){const rows=[],row=[];let cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push([...row]);row.length=0;cell=''}else cell+=c;}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(quote)throw Error('CSV chưa đóng dấu nháy kép');return rows}
function csvToQuestions(raw){const rows=csvParse(raw.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('CSV phải có dòng tiêu đề và ít nhất 1 câu');const headers=rows.shift().map(x=>x.trim());const needed=['id','grade','chapter','lesson','level','competency','stem','optionA','optionB','optionC','optionD','answer','explanation'];if(needed.some(k=>!headers.includes(k)))throw Error('CSV thiếu cột: '+needed.filter(k=>!headers.includes(k)).join(', '));return rows.map(row=>{const v=Object.fromEntries(headers.map((h,i)=>[h,(row[i]||'').trim()]));const answerIndex='ABCD'.indexOf((v.answer||'').toUpperCase());return {id:v.id,grade:Number(v.grade),chapter:v.chapter,lesson:v.lesson,type:'mcq',level:v.level,competency:v.competency,stem:v.stem,options:[v.optionA,v.optionB,v.optionC,v.optionD],answer:answerIndex,explanation:v.explanation,hint:'Nhắc lại khái niệm cốt lõi và kiểm tra đơn vị.',sourceId:v.sourceId||'USER',sourceMode:'user_upload',status:'draft',version:1,misconceptions:{}}})}
function importBank(file){const reader=new FileReader();reader.onload=()=>{try{const raw=String(reader.result);let arr;if(/\.csv$/i.test(file.name)){arr=csvToQuestions(raw)}else{let payload=JSON.parse(raw);arr=Array.isArray(payload)?payload:payload.questions}if(!Array.isArray(arr)||!arr.length)throw Error('Tệp phải chứa mảng câu hỏi hoặc {questions:[...]}');const known=new Set(store.bank.map(q=>String(q.id))),stems=new Set(store.bank.map(q=>(q.grade+'|'+q.stem.trim().toLowerCase())));for(const [i,q] of arr.entries()){const err=validate(q,known);if(err)throw Error('Câu '+(i+1)+': '+err);const sig=q.grade+'|'+q.stem.trim().toLowerCase();if(stems.has(sig))throw Error('Câu '+(i+1)+': trùng nội dung câu hỏi hiện có');stems.add(sig);known.add(String(q.id));if(!chapterMeta(q.grade).some(c=>c.name===q.chapter&&c.lessons.includes(q.lesson)))throw Error('Câu '+(i+1)+': chương/bài chưa khớp danh mục KNTT');q.grade=Number(q.grade);q.status='draft';q.sourceMode=q.sourceMode||'user_upload';q.sourceId=q.sourceId||'USER';q.version=Number(q.version)||1}store.bank.push(...arr);storage.save(store);alert('Đã nhập '+arr.length+' câu nháp. Cần giáo viên Duyệt từng câu sau kiểm tra đáp án và bản quyền.');render()}catch(e){alert('Nhập thất bại: '+e.message)}};reader.onerror=()=>alert('Không đọc được tệp ngân hàng');reader.readAsText(file,'utf-8')}
function downloadTemplate(){const rows=[['id','grade','chapter','lesson','level','competency','stem','optionA','optionB','optionC','optionD','answer','explanation','sourceId'],['VD-MOI-001','10',CAT['10'][0].name,CAT['10'][0].lessons[0],'NB','HH1','Nguyên tử trung hòa có Z = 6 gồm bao nhiêu electron?','6','12','3','8','A','Số electron bằng Z khi nguyên tử trung hòa.','GIAO_VIEN']];const output='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');exportFile('CHEM_MAP_mau_nhap_MCQ.csv',output,'text/csv;charset=utf-8')}

function clickAction(action,el){switch(action){case 'goto-practice':nav('practice');break;case 'goto-map':nav('map');break;case 'goto-plan':nav('plan');break;case 'goto-coverage':nav('coverage');break;case 'retry-wrong':retryWrong();break;case 'transfer-wrong':transferWrong();break;case 'print-result':window.print();break;case 'export-coverage':exportCoverage();break;case 'export-backup':exportBackup();break;case 'start':start();break;case 'new-quiz':state.result=null;state.setup.mode='remedial';state.view='practice';render();break;case 'next':{let s=state.session;if(s.step<s.questions.length-1)s.step++;render();break}case 'prev':{let s=state.session;if(s.step>0)s.step--;render();break}case 'submit':submit();break;case 'hint':{let q=state.session.questions[state.session.step];state.session.seenHint[q.id]=!state.session.seenHint[q.id];render();break}case 'back-setup':if(confirm('Thoát phiên làm bài hiện tại? Bài chưa nộp sẽ không lưu.')){state.session=null;render()}break;case 'goto-sources':nav('sources');break;case 'download-template':downloadTemplate();break;case 'export-bank':exportFile('CHEM_MAP_question_bank.json',JSON.stringify(store.bank,null,2),'application/json;charset=utf-8');break;case 'export-csv':exportCSV();break;case 'add-mcq':addMcq();break;case 'reset':if(confirm('Xóa toàn bộ câu tự thêm và lịch sử làm bài trong trình duyệt này?')){store={bank:structuredClone(window.CHEM_MAP_SEED),attempts:[],student:'HS demo'};storage.save(store);nameInput.value=store.student;state.search='';nav('home')}break}}
function render(){if(state.view==='home')screen.innerHTML=home();if(state.view==='practice')screen.innerHTML=practice();if(state.view==='map')screen.innerHTML=skillMap();if(state.view==='plan')screen.innerHTML=learningPlan();if(state.view==='coverage')screen.innerHTML=coverage();if(state.view==='history')screen.innerHTML=history();if(state.view==='teacher')screen.innerHTML=teacher();if(state.view==='sources')screen.innerHTML=sources()}
nameInput.addEventListener('change',()=>{const v=nameInput.value.trim().slice(0,28)||'HS demo';store.student=v;nameInput.value=v;storage.save(store);render()});
document.getElementById('navigation').addEventListener('click',ev=>{let b=ev.target.closest('[data-view]');if(b)nav(b.dataset.view)});
screen.addEventListener('click',ev=>{let b=ev.target.closest('[data-action]');if(b)clickAction(b.dataset.action,b);let lesson=ev.target.closest('[data-open-lesson]');if(lesson){const args=lesson.dataset.openLesson.split('|').map(Number);openLesson(...args);return;}
let approve=ev.target.closest('[data-approve-id]');if(approve){const q=store.bank.find(q=>q.id===approve.dataset.approveId);if(q&&confirm('Bạn đã kiểm tra tính đúng của đáp án, lời giải, bản quyền, vị trí chương/bài và muốn duyệt câu này?')){q.status='approved';storage.save(store);render()}return;}let a=ev.target.closest('[data-open-attempt]');if(a){state.result=store.attempts.find(x=>x.id===a.dataset.openAttempt)||null;if(state.result){state.view='practice';document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view==='practice'));render();window.scrollTo(0,0)}}});
screen.addEventListener('change',ev=>{const t=ev.target;if(t.dataset.setup){state.setup[t.dataset.setup]=t.value;if(t.dataset.setup==='grade'){state.setup.chapter='all';state.setup.lesson='all'}if(t.dataset.setup==='chapter')state.setup.lesson='all';state.error='';render();return}if(t.id==='map-grade'){state.setup.grade=t.value;render();return}if(t.id==='coverage-grade'){state.coverageGrade=t.value;render();return}if(t.id==='import-backup'&&t.files?.[0]){importBackup(t.files[0]);return}if(t.id==='import-json'&&t.files?.[0]){importBank(t.files[0]);return}const s=state.session;if(!s)return;let q=s.questions[s.step];if(t.name==='mcq'){s.answers[q.id]=Number(t.value)}else if(t.name?.startsWith('tf')){let i=Number(t.name.slice(2)),r=s.answers[q.id]||['','','',''];r[i]=t.value;s.answers[q.id]=r} });
screen.addEventListener('input',ev=>{const s=state.session,t=ev.target;if(t.id==='search-bank'){state.search=t.value;const sel=t.selectionStart;render();let el=document.getElementById('search-bank');if(el){el.focus();el.setSelectionRange(sel,sel)}return}if(!s)return;let q=s.questions[s.step];if(t.id==='short-answer'||t.id==='essay-answer')s.answers[q.id]=t.value});
render();
})();
